def get_divisors(n):
    divisors = []
    i = 1
    while i * i <= n:
        if n % i == 0:
            if i > 1:
                divisors.append(i)
            if i != n // i and n // i > 1:
                divisors.append(n // i)
        i += 1
    return sorted(divisors)

def prime_factors(n):
    factors = set()
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors.add(d)
            n //= d
        d += 1
    if n > 1:
        factors.add(n)
    return factors

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // math.gcd(a, b)

def solve(n):
    divisors = get_divisors(n)
    if not divisors:
        return "0\n0"

    primes = prime_factors(n)

    # Group divisors by their prime factors
    by_prime = defaultdict(list)
    for d in divisors:
        d_primes = [p for p in primes if d % p == 0]
        if d_primes:
            for p in d_primes:
                by_prime[p].append(d)

    # Build the sequence
    # Start with a divisor that has the most prime factors
    start = max(divisors, key=lambda d: len([p for p in primes if d % p == 0]))
    visited = {start}
    order = [start]
    current_primes = set([p for p in primes if start % p == 0])

    # Try to build a path through all divisors
    for _ in range(len(divisors)):
        found = False
        for p in current_primes:
            for d in by_prime[p]:
                if d not in visited:
                    visited.add(d)
                    order.append(d)
                    current_primes = set([p]) & set([p for p in primes if d % p == 0])
                    found = True
                    break
            if found:
                break

        if not found and len(visited) < len(divisors):
            # If no extension found, start fresh from another divisor
            for d in divisors:
                if d not in visited:
                    # Break the current chain and start new
                    order = [d]
                    visited = {d}
                    current_primes = set([p for p in primes if d % p == 0])
                    found = True
                    break

    # Simple fallback: arrange by trying to group by prime factors
    if len(order) != len(divisors):
        # Fallback approach
        order = divisors[:]

    count = 0
    for i in range(1, len(order)):
        if math.gcd(order[i-1], order[i]) == 1:
            count += 1

    # Format output
    parts = ' '.join(map(str, order))
    return f"{parts}\n{count}\n"

