    n = int(lines[0])
    points = []
    for i in range(1, n + 1):
        x, y = map(int, lines[i].split())
        points.append((x, y))

    def cross_product(o, a, b):
        """Cross product of vectors OA and OB"""
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    def on_segment(p, a, b):
        """Check if point p lies on segment ab (assuming p is on the line)"""
        return min(a[0], b[0]) <= p[0] <= max(a[0], b[0]) and \
               min(a[1], b[1]) <= p[1] <= max(a[1], b[1])

    def seg_intersect(a, b, c, d):
        """Check if segment ab intersects segment cd (properly, not at endpoints)"""
        cp1 = cross_product(c, d, a)
        cp2 = cross_product(c, d, b)
        cp3 = cross_product(a, b, c)
        cp4 = cross_product(a, b, d)

        if ((cp1 > 0 and cp2 < 0) or (cp1 < 0 and cp2 > 0)) and \
           ((cp3 > 0 and cp4 < 0) or (cp3 < 0 and cp4 > 0)):
            return True

        # Check endpoint cases (for collinear points)
        if cp1 == 0 and on_segment(a, c, d):
            return True
        if cp2 == 0 and on_segment(b, c, d):
            return True
        if cp3 == 0 and on_segment(c, a, b):
            return True
        if cp4 == 0 and on_segment(d, a, b):
            return True

        return False

    def contains(other, test):
        """Check if triangle 'other' contains point 'test'"""
        a, b, c = other
        cp1 = cross_product(a, b, test)
        cp2 = cross_product(b, c, test)
        cp3 = cross_product(c, a, test)

