        adj[u].append((v, x))
        adj[v].append((u, x))

    train_routes = []
    for i in range(k):
        s, y = map(int, lines[1 + m + i].split())
        train_routes.append((s, y))

    # Compute shortest distances from capital to all cities using only roads
    dist_roads = {}
    pq = [(0, 1)]
    dist_roads[1] = 0

    while pq:
        d, u = heapq.heappop(pq)

        if u in dist_roads and dist_roads[u] < d:
            continue

        for v, w in adj[u]:
            new_dist = d + w
            if v not in dist_roads or dist_roads[v] > new_dist:
                dist_roads[v] = new_dist
                heapq.heappush(pq, (new_dist, v))

    # Count trains that can be closed
    # A train route to city s with weight y can be closed if
    # the shortest distance to s using only roads is <= y
    ans = 0
    for s, y in train_routes:
        if s in dist_roads and dist_roads[s] <= y:
            ans += 1

    return str(ans)

