def solution(input_str):
    """
    Compute fr(n) for each query.
    fr(n) = product over all prime powers p^a | n of g(r, a)
    where g(r, a) = C(a+r, a) + C(a+r-1, a-1)

    Using the identity: C(n, k) + C(n-1, k-1) = C(n, k) doesn't work directly,
    but C(n, k) + C(n-1, k-1) = C(n, k) + C(n-1, n-k) for our purposes.

    Actually: g(r, a) = C(a+r, a) + C(a+r-1, a-1)
    This simplifies using Pascal's identity: C(n,k) + C(n-1,k-1) = C(n,k)
    Wait, let me recalculate: C(a+r, a) + C(a+r-1, a-1) = C(a+r+1, a)

    Actually the formula is: g(r, a) = C(a+r, a) + C(a+r-1, a-1)
    Using C(n,k) = C(n, n-k): C(a+r-1, a-1) = C(a+r-1, r)
    And C(a+r, a) = C(a+r, r)
    So g(r, a) = C(a+r, r) + C(a+r-1, r) = C(a+r+1, r+1)

    Let me verify: g(r, a) = C(a+r+1, r+1)
    For r=0, a=1: C(2, 1) = 2 ✓
    For r=4, a=1: C(6, 5) = 6 ✓
    For r=3, a=1: C(5, 4) = 5 ✓
    For r=2, a=1: C(4, 3) = 4 ✓
    For r=4, a=4: C(9, 5) = 126... but we need 105

    Let me use the direct formula instead.
    """

    MOD = 10**9 + 7
    MAX = 2010000  # Maximum r + n value

    # Precompute factorials
    fact = [1] * MAX
    invFact = [1] * MAX

    for i in range(1, MAX):
        fact[i] = fact[i-1] * i % MOD

    invFact[MAX-1] = pow(fact[MAX-1], MOD-2, MOD)
    for i in range(MAX-2, -1, -1):
        invFact[i] = invFact[i+1] * (i+1) % MOD

    def nCr(n, k):
        if k < 0 or k > n:
            return 0
        return fact[n] * invFact[k] % MOD * invFact[n-k] % MOD

    def g(r, a):
        """Compute g(r, a) = C(a+r, a) + C(a+r-1, a-1)"""
        term1 = nCr(a + r, a)
        term2 = nCr(a + r - 1, a - 1) if a >= 1 else 0
        return (term1 + term2) % MOD

    lines = input_str.strip().split('\n')
