                count = 0
                while temp_n % p == 0:
                    count += 1
                    temp_n //= p
                ans = ans * g(r, count) % MOD
            p += 1

        if temp_n > 1:
            ans = ans * g(r, 1) % MOD

        result.append(str(ans))

    return '\n'.join(result) + '\n'


