                pos_to_frogs[f['pos']].remove(f)
                if not pos_to_frogs[f['pos']]:
                    del pos_to_frogs[f['pos']]

            # Update frog to end_pos
            # Remove from old pos tracking (already done above)
            # Add to new pos tracking
            if end_pos not in pos_to_frogs:
                pos_to_frogs[end_pos] = []
            pos_to_frogs[end_pos].append(f)

    # Collect remaining frog indices
    remaining_indices = [f['id'] for f in frogs if f['active']]

    result = str(len(remaining_indices)) + '\n' + ' '.join(map(str, remaining_indices)) + ' '
    return result

